       .dialog-icon {
         flex: 0 0 auto;
         width: 3rem;
         height: 3rem;
         border-radius: 999px;
         display: grid;
         place-items: center;
         background: linear-gradient(180deg, rgba(255, 107, 122, 0.24), rgba(255, 107, 122, 0.08));
         color: #ffd0d6;
         border: 1px solid rgba(255, 141, 152, 0.35);
