         margin: 0.4rem 0 0;
         color: var(--muted);
       }

       .dialog-actions {
         display: flex;
         justify-content: flex-end;
         gap: 0.75rem;
         flex-wrap: wrap;
         margin-top: 1.4rem;
       }

       .secondary {
         background: transparent;
         border-color: var(--border);
       }

