           --bg: Canvas;
           --bg-elevated: Canvas;
           --bg-surface: Canvas;
           --bg-surface-2: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: ButtonBorder;
           --accent: Highlight;
           --danger: ButtonText;
           --danger-strong: ButtonText;
