   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div class="page" data-component="ImagePreviewPage"></div>
     </main>

     <script>
       function ImagePreviewPage() {
         return `
           <h1>Image Preview</h1>
           <p class="subtitle">Review this image before deciding whether to keep it in your library.</p>
           <section class="preview-card" aria-labelledby="preview-title">
             <div class="image-frame">
               <img
                 src="https://images.unsplash.com/photo-1524063436528-4d4b0e0f2a1f?auto=format&fit=crop&w=1200&q=80"
                 alt="A moody portrait of a camera beside a coffee cup on a desk"
               />
             </div>
             <div class="meta">
               <div class="details">
                 <h2 id="preview-title">Desk still life</h2>
                 <p>Uploaded today · 4.2 MB</p>
               </div>
               <div class="button-row">
                 <button class="trigger" type="button" data-open-delete-dialog>
                   Delete image
                 </button>
               </div>
             </div>
           </section>
         `;
       }

       function DeleteDialog() {
         return `
           <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
             <div class="dialog-shell">
               <div class="dialog-header">
                 <div class="dialog-icon" aria-hidden="true">
                   <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                     <path d="M12 9v5"></path>
                     <path d="M12 17.5v.5"></path>
                     <path d="M10.3 4.9 2.8 18a2 2 0 0 0 1.7 3h15a2 2 0 0 0 1.7-3L13.7 4.9a2 2 0 0 0-3.4 0Z"></path>
                   </svg>
                 </div>
                 <div>
                   <h2 id="delete-dialog-title" class="dialog-title">Delete this image?</h2>
                   <p id="delete-dialog-description" class="dialog-copy">
                     This will remove the image from your library. You can&apos;t undo this action.
                   </p>
                 </div>
               </div>
               <div class="dialog-actions">
                 <button type="button" class="secondary" data-close-dialog>Cancel</button>
                 <button type="button" class="danger" data-confirm-delete>Delete image</button>
               </div>
             </div>
           </dialog>
         `;
       }

       function App() {
         return ImagePreviewPage() + DeleteDialog();
       }

       const root = document.querySelector('[data-component="ImagePreviewPage"]');
       root.innerHTML = App();

       const dialog = document.getElementById('delete-dialog');
       const openButton = document.querySelector('[data-open-delete-dialog]');
       const closeButton = document.querySelector('[data-close-dialog]');
       const confirmButton = document.querySelector('[data-confirm-delete]');

       let lastFocusedTrigger = null;

       openButton.addEventListener('click', () => {
         lastFocusedTrigger = document.activeElement;
         dialog.showModal();
         closeButton.focus();
       });

       closeButton.addEventListener('click', () => {
         dialog.close();
       });

       confirmButton.addEventListener('click', () => {
         dialog.close();
       });

       dialog.addEventListener('close', () => {
         if (lastFocusedTrigger && typeof lastFocusedTrigger.focus === 'function') {
           lastFocusedTrigger.focus();
         }
       });
     </script>
   </body>
